fix_ops.new:
e.preventDefault();
const msg = document.getElementById('msg');
if (!cart.length) { msg.textContent = 'Your cart is empty'; return; }
const btn = e.target.querySelector('button[type=submit]');
btn.disabled = true;
try {
  const res = await fetch('/api/order', {method: 'POST', body: JSON.stringify({items: cart})});
  msg.textContent = res.ok ? 'Order received' : 'Order failed';
} catch (err) {
  msg.textContent = 'Order failed: network error';
} finally { btn.disabled = false; }
